function friendlySteps(task: CourseLesson) {
  return task.steps.map((step, index) => {
    const prefix = `Шаг ${index + 1}. `;
    if (typeof step !== "string") return step;
    return step.startsWith(prefix) ? step : `${prefix}${step}`;
  });
}

function describeLocatorSearch(steps: CourseLesson["steps"]): CourseLesson["steps"] {
  const replaceInstruction = (instruction: string) => instruction
    .replace(/getByRole\((['"])(button|link|heading)\1,\s*\{\s*name:\s*(['"])([^'"]*)\3\s*\}\)/g, "локатор реального элемента с ролью «$2» и доступным именем «$4»")
    .replace(/getByLabel\((['"])([^'"]*)\1\)/g, "локатор реального поля с подписью «$2»")
    .replace(/getByTestId\((['"])([^'"]*)\1\)/g, "локатор реального элемента с data-testid «$2»")
    .replace(/getByText\((['"])([^'"]*)\1[^)]*\)/g, "локатор реального текста «$2»");

  return steps.map((step) => typeof step === "string"
    ? replaceInstruction(step)
    : { ...step, instruction: replaceInstruction(step.instruction) });
}

