const codingLessonIds = [
  "0.4", "0.5", "1.1", "1.2", "1.3", "1.4", "1.5", "1.6", "1.7", "1.8", "1.9",
  "2.1", "2.2", "2.3", "2.4", "2.5", "2.6", "2.7", "2.8",
  "3.1", "3.2", "3.3", "3.4", "3.5", "3.6", "3.7", "4.1", "4.2", "4.3", "4.4", "4.5", "4.6",
  "5.1", "5.2", "5.3", "5.4", "5.5", "5.6", "6.1", "6.2", "6.3", "6.4", "6.5", "6.6", "6.7", "6.8",
  "5.7", "5.8", "5.9", "6.9", "6.10", "6.11",
  "7.1", "7.2", "7.3", "7.4", "8.2", "8.3", "8.4", "8.5", "9.2", "9.3", "9.4",
  "8.6", "8.7",
] as const;

function validateExplicitCodeCoverage() {
  const missing = codingLessonIds.filter((lessonId) => {
    const snippets = Object.values(explicitStepCode[lessonId] ?? {}).flat();
    return !snippets.length || snippets.some((snippet) => !snippet.file || !snippet.language || !snippet.code.trim() || !snippet.description);
  });
  if (missing.length) throw new Error(`Missing explicit code snippets for lessons: ${missing.join(", ")}`);
}

validateExplicitCodeCoverage();

function addExplicitStepCode(key: string, steps: CourseLesson["steps"]): CourseLesson["steps"] {
  const snippetsByStep = explicitStepCode[key];
  if (!snippetsByStep) return steps;

  return steps.map((step, index) => {
    const snippets = snippetsByStep[index]?.map((snippet) => ({
      ...snippet,
      ...hideConcreteLocators({ title: snippet.file, language: snippet.language, code: snippet.code, description: snippet.description }),
    }));
    if (!snippets) return step;
    return {
      instruction: typeof step === "string" ? step : step.instruction,
      snippets,
    };
  });
}

function explicitSolutionExamples(key: string): CodeExample[] | undefined {
  const snippets = Object.values(explicitStepCode[key] ?? {}).flat();
  if (!snippets.length) return undefined;

  return snippets.map((snippet) => ({
    title: snippet.file,
    description: `Эталон для шага урока: ${snippet.description}`,
    language: snippet.language,
    code: snippet.code,
  }));
}

const locatorPlaceholder = "ВСТАВЬТЕ ЛОКАТОР РЕАЛЬНОГО ЭЛЕМЕНТА";

function hideConcreteLocators(example: CodeExample): CodeExample {
  const code = example.code
    .replace(/getByRole\((['"])(button|link|heading)\1,\s*\{\s*name:\s*(['"])[^'"]*\3\s*\}\)/g, 'getByRole("$2", { name: "ВСТАВЬТЕ ДОСТУПНОЕ ИМЯ РЕАЛЬНОГО ЭЛЕМЕНТА" })')
    .replace(/getByLabel\((['"])[^'"]*\1\)/g, 'getByLabel("ВСТАВЬТЕ ПОДПИСЬ РЕАЛЬНОГО ПОЛЯ")')
    .replace(/getByTestId\((['"])[^'"]*\1\)/g, 'getByTestId("ВСТАВЬТЕ data-testid РЕАЛЬНОГО ЭЛЕМЕНТА")')
    .replace(/getByText\((['"])[^'"]*\1(,\s*\{[^}]*\})?\)/g, 'getByText("ВСТАВЬТЕ ВИДИМЫЙ ТЕКСТ РЕАЛЬНОГО ЭЛЕМЕНТА"$2)')
    .replace(/page\.locator\((['"])[^'"]*\1\)/g, `page.locator("${locatorPlaceholder}")`)
    .replace(/page\.dragAndDrop\((['"])[^'"]*\1,\s*(['"])[^'"]*\2\)/g, `page.dragAndDrop("${locatorPlaceholder}", "${locatorPlaceholder}")`);

  return {
    ...example,
    description: `${example.description ?? "Эталонный шаблон."} Найдите локатор самостоятельно в Inspector и замените отмеченное место.`,
    code,
  };
}

export function adaptLessonForBeginner(task: CourseLesson): CourseLesson {
  const key = `${task.moduleId}.${task.id.split(".")[1]}`;
  // Уроки модуля 1 — исходный, уже согласованный путь для новичка.
  // Не подменяем его старыми промежуточными черновиками из taskGuides.
  const override = task.moduleId === "1" || task.moduleId === "2" ? undefined : taskGuides[key];
  const solution = task.solutionExamples?.length
    ? task.solutionExamples
    : task.codeExamples?.length
      ? task.codeExamples
      : undefined;

  return {
    ...task,
    ...override,
    reuseHint: task.id.endsWith(".1") ? moduleReuseHints[task.moduleId] : undefined,
    summary: override?.summary ?? `После урока вы сможете: ${task.summary.charAt(0).toLowerCase()}${task.summary.slice(1)}`,
    context: override?.context ?? `Проблема: ${task.context} Не нужно знать всё заранее: сначала разберитесь, какую проблему решает метод, затем идите по шагам и сверяйтесь со словарём.`,
    theory: [
      `Почему это помогает в автотестах: ${moduleMethodWhy[task.moduleId]}`,
      ...(override?.theory ?? task.theory.map((item) => item.replace(/assertion/gi, "проверку результата"))),
    ],
    steps: describeLocatorSearch(addExplicitStepCode(key, override?.steps ?? friendlySteps(task))),
    terms:
      override?.terms ??
      (task.terms?.length
        ? task.terms
        : lessonTerms[key] ?? moduleTerms[task.moduleId]),
    solutionExamples: (override?.solutionExamples ?? solution ?? explicitSolutionExamples(key))?.map(hideConcreteLocators),
  };
}
